const release='https://github.com/RorriMaesu/Anatomy-Studio-Organs-Cavities-Membranes/releases/latest';
const download=release+'/download/Soma-Setup.exe';
let step=0;
const ua=navigator.userAgent;
let browser=/Edg\//.test(ua)?'edge':/Firefox\//.test(ua)?'firefox':'chrome';
const illustrative=(title,body)=>`<figure><div class="illustration"><small>ILLUSTRATION · NOT A SCREENSHOT</small><h3>${title}</h3>${body}</div><figcaption>Use the written instructions for your version. Buttons and wording may differ.</figcaption></figure>`;
const stop='<p class="stop"><strong>A different warning?</strong> Stop if it reports a virus, malware, unwanted software, an insecure connection, or an administrator block. Do not turn off protection or switch browsers to escape a warning. Use the online studio or ask your school’s IT team.</p>';
const browsers={
 edge:{name:'Microsoft Edge',text:`<ol><li>Press <strong>Ctrl + J</strong> to open Downloads. Find <strong>Soma-Setup.exe</strong>.</li><li>If the message specifically says <strong>isn't commonly downloaded</strong>, open that entry's <strong>…</strong> menu and choose <strong>Keep</strong> to review the details.</li><li>Check the name and source. Our current preview shows <strong>Publisher: Unknown</strong>. That means Windows has not verified our publisher identity.</li><li>If you understand and accept this risk, the warning's menu beside <strong>Delete</strong> may offer <strong>Keep anyway</strong>, as in the screenshot. Otherwise choose Cancel or Delete.</li><li>After the download finishes, choose <strong>Open file</strong>. Continue to the Windows step.</li></ol>`,visual:'<figure><a href="assets/edge-uncommon.png" target="_blank" rel="noopener"><img class="screenshot" src="assets/edge-uncommon.png" alt="Actual Edge warning for Soma-Setup.exe. Publisher is Unknown. At the bottom, the menu next to Delete contains Keep anyway."></a><figcaption>Actual Edge screenshot. The menu at the bottom contains “Keep anyway.” Open the image to enlarge it.</figcaption></figure>'},
 chrome:{name:'Google Chrome',text:`<ol><li>Press <strong>Ctrl + J</strong> to open download history. Find <strong>Soma-Setup.exe</strong> and expand its warning details.</li><li>Read the reason. <strong>Suspicious</strong> can mean unfamiliar, but can also have other causes. Do not assume every warning is just low download popularity.</li><li>If offered, <strong>Check for malware</strong> sends the file to Google's service for checking. This is optional and is separate from Soma’s local AI.</li><li>Only if the details concern an unfamiliar download, you verified our release page, and you accept the risk, review the available keep/download option. Its name varies by Chrome version; some show <strong>Download suspicious file</strong>. Cancellation remains the safer choice if uncertain.</li><li>If completed, open the downloaded file and continue to the Windows step.</li></ol>`,visual:illustrative('Chrome · download history','<p><b>Ctrl + J</b> → Soma-Setup.exe</p><p>Expand the warning and read its reason.</p><span class="chip">Check for malware (if offered)</span><p>Review the result before deciding whether to continue.</p>')},
 firefox:{name:'Mozilla Firefox',text:`<ol><li>Press <strong>Ctrl + J</strong> or open the toolbar's Downloads arrow. Find <strong>Soma-Setup.exe</strong>.</li><li>If it specifically says <strong>This file is not commonly downloaded</strong>, select the right-facing arrow beside the entry to read more.</li><li>After checking the source, if you accept the risk, use <strong>Allow Download</strong> when offered. It may also appear when you right-click the pending entry.</li><li>Wait for completion, then open the file. Windows may still display its own prompt; continue to the next step.</li></ol>`,visual:illustrative('Firefox · Downloads','<p>Soma-Setup.exe <span class="chip">›</span></p><p>This file is not commonly downloaded.</p><span class="chip">Allow Download</span><p>Only for the unfamiliar-file case described here.</p>')}
};
function render(){
 document.querySelectorAll('[data-step]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.step)===step)));
 document.querySelector('#back').disabled=step===0;document.querySelector('#next').disabled=step===3;document.querySelector('#position').textContent=`Step ${step+1} of 4`;
 const panels=[`<div class="step-copy"><p class="eyebrow">STEP 1 · BEFORE DOWNLOADING</p><h2>Start at the official release.</h2><ol><li>Open the release page below. Its address must start with <code>https://github.com/RorriMaesu/Anatomy-Studio-Organs-Cavities-Membranes/releases/</code>.</li><li>Read the version notes and select <strong>Soma-Setup.exe</strong> under Assets. Avoid copies in messages or advertisements.</li><li>This preview is for <strong>Intel/AMD 64-bit Windows 10 22H2 or Windows 11</strong>. The installer is about 20 MB; local AI models need several GB more. No subscription or payment is required.</li></ol><div class="links"><a class="button primary" href="${release}" target="_blank" rel="noopener">Check release & download ↗</a><a class="button" href="${download}">Download installer</a></div><details><summary>Optional: compare the file checksum</summary><p>The release includes SHA256SUMS.txt. A matching SHA-256 hash confirms you have the same bytes listed in that release; it is not a publisher signature or a safety guarantee.</p></details></div>`,
 `<p class="eyebrow">STEP 2 · BROWSER DOWNLOAD</p><h2>Choose the browser you use.</h2><p>The suggested browser can be changed below. If no warning appears, open the completed download and move to Step 3.</p><div class="browser-picker" aria-label="Browser">${Object.entries(browsers).map(([id,b])=>`<button data-browser="${id}" aria-pressed="${id===browser}">${b.name}</button>`).join('')}</div><div class="grid"><div>${browsers[browser].text}${stop}</div>${browsers[browser].visual}</div>`,
 `<p class="eyebrow">STEP 3 · WINDOWS & INSTALLATION</p><h2>A separate Windows check may appear.</h2><div class="grid"><div><ol><li>If Windows says <strong>Windows protected your PC</strong> because the app is unrecognized, choose <strong>More info</strong> to inspect the app name and publisher.</li><li>Confirm <strong>Soma-Setup.exe</strong>. Our unsigned preview shows <strong>Unknown publisher</strong>. Only if you trust this release and accept that risk, choose <strong>Run anyway</strong> when Windows offers it. Otherwise choose <strong>Don't run</strong>.</li><li>If there is no Run anyway option, or Smart App Control or your school blocks it, stop. Keep studying in the browser.</li><li>In the Soma installer, review the destination folder and install. Open <strong>Soma Desktop</strong> from the Start menu afterward.</li></ol>${stop}</div>${illustrative('Windows protected your PC','<p>Unrecognized-app prompt</p><span class="chip">More info</span><p>App: Soma-Setup.exe<br>Publisher: Unknown publisher</p><span class="chip">Run anyway (if available)</span><span class="chip">Don’t run</span>')}</div>`,
 `<div class="step-copy"><p class="eyebrow">STEP 4 · YOUR LOCAL STUDY PARTNER</p><h2>Let Soma guide the remaining setup.</h2><ol><li>Open Soma Desktop. It checks whether Ollama is installed and running and whether you already have models.</li><li>If needed, use the offered Ollama installation step. Review the official installer and its destination. If Ollama is already installed but stopped, use Soma’s start button.</li><li>Choose an existing model or download the recommended one. Check free space first; model downloads can be several GB. AI settings lets you review storage choices.</li><li>Complete the readiness check, then choose <strong>Ask your tutor</strong> or <strong>Practice a quiz</strong>. Use the textbook links to verify explanations.</li></ol><p>Only the AI companion needs desktop setup. You can start Chapter 3 now:</p><div class="links"><a class="button primary" href="../../chapter3/">Open Cell Studio →</a><a class="button" href="../">Return to companion page</a></div></div>`];
 document.querySelector('#step').innerHTML=panels[step];
 document.querySelectorAll('[data-browser]').forEach(b=>b.onclick=()=>{browser=b.dataset.browser;render();document.querySelector(`[data-browser="${browser}"]`).focus();});
}
function go(n){step=n;render();document.querySelector('#step').focus();}
document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>go(Number(b.dataset.step)));
document.querySelector('#back').onclick=()=>go(Math.max(0,step-1));document.querySelector('#next').onclick=()=>go(Math.min(3,step+1));render();
